effect.shader:
float u_xlat0;
bvec3 u_xlatb0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec3 u_xlat4;
float u_xlat8;
void main()
{
    u_xlat0 = dot(_blue_color.xy, vec2(_red_intensity, _green_intensity));
    u_xlat0 = (-u_xlat0) + _blue_color.z;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat4.xyz = u_xlat1.xzy * vec3(_red_intensity, _blue_intensity, _green_intensity);
    u_xlat4.xyz = u_xlat4.yzz + u_xlat4.xxy;
    u_xlat4.xyz = (-u_xlat4.xyz) + u_xlat1.yzx;
    u_xlat0 = u_xlat4.y / u_xlat0;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat0 = (-u_xlat0) + 1.0;
    u_xlat8 = (-u_xlat0) * u_xlat1.w + 1.0;
    u_xlat2.w = u_xlat1.w * u_xlat0;
    u_xlat2.xyz = (-_blue_color.xyz) * vec3(u_xlat8) + u_xlat1.xyz;
    u_xlat2.xyz = clamp(u_xlat2.xyz, 0.0, 1.0);
    u_xlat0 = dot(u_xlat2.xy, vec2(0.5, 0.5));
    u_xlat2.z = min(u_xlat0, u_xlat2.z);
    u_xlat0 = dot(_red_color.zy, vec2(_blue_intensity, _green_intensity));
    u_xlat0 = (-u_xlat0) + _red_color.x;
    u_xlat0 = u_xlat4.z / u_xlat0;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat0 = (-u_xlat0) + 1.0;
    u_xlat8 = (-u_xlat0) * u_xlat1.w + 1.0;
    u_xlat3.w = u_xlat1.w * u_xlat0;
    u_xlat3.xyz = (-_red_color.xyz) * vec3(u_xlat8) + u_xlat1.xyz;
    u_xlat3.xyz = clamp(u_xlat3.xyz, 0.0, 1.0);
    u_xlat0 = dot(u_xlat3.zy, vec2(0.5, 0.5));
    u_xlat3.x = min(u_xlat0, u_xlat3.x);
    u_xlatb0.xz = equal(ivec4(int(_key_mode), int(_key_mode), int(_invert), int(_key_mode)), ivec4(1, 0, 1, 0)).xz;
    u_xlat2 = (u_xlatb0.x) ? u_xlat2 : u_xlat3;
    u_xlat0 = dot(_green_color.xz, vec2(_red_intensity, _blue_intensity));
    u_xlat0 = (-u_xlat0) + _green_color.y;
    u_xlat0 = u_xlat4.x / u_xlat0;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat0 = (-u_xlat0) + 1.0;
    u_xlat4.x = (-u_xlat0) * u_xlat1.w + 1.0;
    u_xlat3.w = u_xlat1.w * u_xlat0;
    u_xlat3.xyz = (-_green_color.xyz) * u_xlat4.xxx + u_xlat1.xyz;
    u_xlat3.xyz = clamp(u_xlat3.xyz, 0.0, 1.0);
    u_xlat0 = dot(u_xlat3.xz, vec2(0.5, 0.5));
    u_xlat3.y = min(u_xlat0, u_xlat3.y);
    u_xlat1 = (int(_key_mode) != 0) ? u_xlat2 : u_xlat3;
    u_xlatb0.x = u_xlat1.w<_alpha_clip;
    u_xlat1.w = (u_xlatb0.x) ? 0.0 : u_xlat1.w;
    u_xlat2 = (-u_xlat1) + vec4(1.0, 1.0, 1.0, 1.0);
    fragColor = (u_xlatb0.z) ? u_xlat2 : u_xlat1;
    return;
}
